from collections import deque

def components(grid):
    h,w=len(grid),len(grid[0]); seen=set(); out=[]
    for r in range(h):
      for c in range(w):
       if grid[r][c] and (r,c) not in seen:
        color=grid[r][c]; q=[(r,c)]; seen.add((r,c)); comp=[]
        while q:
         x,y=q.pop(); comp.append((x,y))
         for p in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
          a,b=p
          if 0<=a<h and 0<=b<w and p not in seen and grid[a][b]==color:
           seen.add(p);q.append(p)
        out.append((color,comp))
    return out

def slide(grid):
    h,w=len(grid),len(grid[0]); objs=components(grid)
    # rightmost objects first, repeatedly move any object one cell if destination does not overlap
    # other current object cells
    for _ in range(w*len(objs)+5):
      moved=False
      objs.sort(key=lambda z:max(c for r,c in z[1]), reverse=True)
      for i,(color,cells) in enumerate(objs):
       own=set(cells); other=set(p for j,(_,cs) in enumerate(objs) if j!=i for p in cs)
       shifted={(r,c+1) for r,c in cells}
       if max(c for r,c in cells)<w-1 and not (shifted & other):
        objs[i]=(color,[(r,c+1) for r,c in cells]); moved=True
      if not moved: break
    res=[[0]*w for _ in range(h)]
    for color,cells in objs:
      for r,c in cells: res[r][c]=color
    return res,objs

